(function(root){
'use strict';
const defaults={seance:'S18',titre:'Du plan au contenu : préparons notre mini-site !',cycle:'Challenge 100 Jours · Automne 2026 · Module 05',date:'2026-11-23',horaire:'',objectif:'Rédiger le contenu de sa page et préparer un prompt maître.',preparation:'Essai S17, carnet exporté, sujet, plan et source vérifiée.',acces:'',supports:'https://elhisse-clprepas.github.io/atelier-seance-17-ln-ia/',replay:'',signature:'Abderrahman EL HISSE\nLAB-NUMÉRIQUE-IA · LN-IA'};
const models={annonce:'🛠️ *ATELIER PRATIQUE — {seance}*\n*{titre}*\n{cycle}\n\n📅 {date}\n🕒 {horaire}\n\nBonjour à toutes et à tous,\n\n🎯 *Notre objectif*\n{objectif}\n\n📂 *À préparer*\n{preparation}\n\n🔗 *Accès à la séance*\n{acces}\n\n📚 *Supports*\n{supports}\n\nL’IA propose. Vous vérifiez, vous testez, vous décidez.\n\n{signature}',rappel:'⏰ *RAPPEL — {seance}*\n*{titre}*\n\n📅 {date} · {horaire}\n\nÀ préparer : {preparation}\n\nAccès : {acces}\n\nÀ bientôt !\n{signature}',ressources:'📚 *RESSOURCES ET REPLAY — {seance}*\n*{titre}*\n\nSupports : {supports}\nReplay : {replay}\n\nPour la suite : {objectif}\nConservez une observation réelle, une correction et une question.\n\n{signature}',suivi:'✍️ *VOTRE PRATIQUE — {seance}*\n*{titre}*\n\n🎯 {objectif}\n\n1. Ouvrez les supports : {supports}\n2. Réalisez votre essai : {preparation}\n3. Notez le résultat observé et gardez une trace.\n\nEn cas de difficulté : précisez le fichier, l’action tentée et le résultat obtenu.\n\n{signature}'};

function dateLabel(v){if(!/^\d{4}-\d{2}-\d{2}$/.test(v))return v;const d=new Date(v+'T12:00:00Z');return Number.isNaN(+d)?v:new Intl.DateTimeFormat('fr-FR',{weekday:'long',day:'numeric',month:'long',year:'numeric',timeZone:'Africa/Casablanca'}).format(d)}
function generate(model,fields){return model.replace(/\{([a-z]+)\}/g,(_,key)=>{const value=key==='date'?dateLabel(fields[key]||''):fields[key];return value&&value.trim()?value:'['+key.toUpperCase()+' À COMPLÉTER]';})}
function normalize(text){return text.replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g,'$1 : $2').replace(/^#{1,6}\s+(.+)$/gm,'*$1*').replace(/\*\*([^*\n]+)\*\*/g,'*$1*')}
function links(text){return [...new Set(text.match(/https?:\/\/[^\s<>]+/g)||[])]}
function validGroup(value){try{const u=new URL(value);return u.protocol==='https:'&&u.hostname==='chat.whatsapp.com'&&/^\/[A-Za-z0-9]+\/?$/.test(u.pathname)&&!u.search&&!u.hash&&!u.username&&!u.password&&!u.port}catch{return false}}
function validateWorkspace(o){if(!o||o.schema!=='lnia-messages'||o.version!==1||typeof o.message!=='string'||!o.fields||!o.models||!Array.isArray(o.versions))throw Error('Format d’espace incompatible.');const fields={},safeModels={};for(const k in defaults){if(typeof o.fields[k]!=='string')throw Error('Paramètre manquant : '+k);fields[k]=o.fields[k]}for(const k in models){if(typeof o.models[k]!=='string')throw Error('Modèle manquant : '+k);safeModels[k]=o.models[k]}return {schema:o.schema,version:1,fields,models:safeModels,message:o.message,versions:o.versions.filter(v=>v&&typeof v.text==='string'&&typeof v.date==='string').slice(-20)}}
root.LNIA={defaults,models,dateLabel,generate,normalize,links,validGroup,validateWorkspace};
})(typeof window==='undefined'?globalThis:window);
